Estes valores não são resistências do concreto do dormente.","documental_concreto":"DOCUMENTAL C57:C68: laudos de adições, compressão, flexão, abatimento, reatividade álcali-agregado, análise petrográfica, mitigação, potencial DEF e água de preparo. As células N58:N62 não informam mínimos de resistência do concreto.","observacao":"Referência consultiva Cavan. Cargas e nominais transcritos do anexo; divergências sinalizadas para confirmação. Não contém resultados medidos de lotes. Parâmetros normativos anteriores identificados foram preservados quando o anexo não os substitui."}]'::jsonb)
  loop
    v_reg := jsonb_populate_record(null::public.especificacoes_dormentes, v_json);
    select count(*) into v_count from public.especificacoes_dormentes
      where upper(btrim(projeto)) = v_reg.projeto and upper(btrim(bitola)) = upper(v_reg.bitola);
    if v_count > 1 then
      raise exception 'Especificações duplicadas para % / %; revisar antes da migração.', v_reg.projeto, v_reg.bitola;
    elsif v_count = 1 then
      update public.especificacoes_dormentes set
